create table if not exists public.post_job_followups(id uuid primary key default gen_random_uuid(),job_id uuid not null references public.jobs(id) on delete cascade,customer_id uuid not null references public.customers(id) on delete cascade,followup_type text not null check(followup_type in ('review','membership','estimate','quality_check')),status text not null default 'pending' check(status in ('pending','completed','dismissed')),due_at timestamptz not null,completed_at timestamptz,notes text,created_at timestamptz not null default now(),unique(job_id,followup_type)); create index if not exists idx_post_job_followups_due on public.post_job_followups(status,due_at); alter table public.post_job_followups enable row level security; revoke all on public.post_job_followups from anon; create policy post_job_followup_read on public.post_job_followups for select to authenticated using(public.has_permission_for_current_user('view_csr') or public.has_permission_for_current_user('view_jobs')); create or replace function private.seed_post_job_followups(p_job_id uuid) returns void language plpgsql security definer set search_path='' as $$ declare v_customer uuid; begin select customer_id into v_customer from public.jobs where id=p_job_id and status in ('work_complete','completed'); if v_customer is null then raise exception 'Completed job required'; end if; insert into public.post_job_followups(job_id,customer_id,followup_type,due_at) values(p_job_id,v_customer,'quality_check',now()+interval '1 day') on conflict do nothing; if not exists(select 1 from public.service_agreements where customer_id=v_customer and status='active') then insert into public.post_job_followups(job_id,customer_id,followup_type,due_at) values(p_job_id,v_customer,'membership',now()+interval '2 days') on conflict do nothing; end if; if exists(select 1 from public.estimates e join public.jobs j on j.id=e.job_id where j.customer_id=v_customer and e.status in ('draft','sent')) then insert into public.post_job_followups(job_id,customer_id,followup_type,due_at) values(p_job_id,v_customer,'estimate',now()+interval '2 days') on conflict do nothing; end if; insert into public.post_job_followups(job_id,customer_id,followup_type,due_at) values(p_job_id,v_customer,'review',now()+interval '1 day') on conflict do nothing; end $$; create or replace function public.seed_post_job_followups(p_job_id uuid) returns void language sql set search_path='' as $$ select private.seed_post_job_followups(p_job_id) $$; revoke all on function public.seed_post_job_followups(uuid) from public,anon; grant execute on function public.seed_post_job_followups(uuid) to authenticated;